<?php

namespace Vnecoms\VendorsCategory\Model\ResourceModel\Category;

class Collection extends \Magento\Framework\Model\ResourceModel\Db\Collection\AbstractCollection
{
    /**
     * Event prefix.
     *
     * @var string
     */
    protected $_eventPrefix = 'ves_vendorscategory_collection';

    /**
     * Event object name.
     *
     * @var string
     */
    protected $_eventObject = 'vendorscategory_collection';

    /**
     * Load with product count flag.
     *
     * @var bool
     */
    protected $_loadWithProductCount = false;

    /**
     * Name of product table.
     *
     * @var string
     */
    private $_productTable;

    protected function _construct()
    {
        $this->_init('Vnecoms\VendorsCategory\Model\Category', 'Vnecoms\VendorsCategory\Model\ResourceModel\Category');
    }

    /**
     * Before collection load.
     *
     * @return $this
     */
    protected function _beforeLoad()
    {
        $this->_eventManager->dispatch($this->_eventPrefix.'_load_before', [$this->_eventObject => $this]);

        return parent::_beforeLoad();
    }

    /**
     * After collection load.
     *
     * @return $this
     */
    protected function _afterLoad()
    {
        $this->_eventManager->dispatch($this->_eventPrefix.'_load_after', [$this->_eventObject => $this]);

        return parent::_afterLoad();
    }

    /**
     * Load collection.
     *
     * @param bool $printQuery
     * @param bool $logQuery
     *
     * @return $this
     */
    public function load($printQuery = false, $logQuery = false)
    {
        if ($this->isLoaded()) {
            return $this;
        }

        parent::load($printQuery, $logQuery);

        if ($this->_loadWithProductCount) {
            $this->_loadProductCount();
        }

        return $this;
    }

    /**
     * Set flag for loading product count.
     *
     * @param bool $flag
     *
     * @return $this
     */
    public function setLoadProductCount($flag)
    {
        $this->_loadWithProductCount = $flag;

        return $this;
    }

    /**
     * Add Id filter.
     *
     * @param array $categoryIds
     *
     * @return $this
     */
    public function addIdFilter($categoryIds)
    {
        if (is_array($categoryIds)) {
            if (empty($categoryIds)) {
                $condition = '';
            } else {
                $condition = ['in' => $categoryIds];
            }
        } elseif (is_numeric($categoryIds)) {
            $condition = $categoryIds;
        } elseif (is_string($categoryIds)) {
            $ids = explode(',', $categoryIds);
            if (empty($ids)) {
                $condition = $categoryIds;
            } else {
                $condition = ['in' => $ids];
            }
        }
        $this->addFieldToFilter('category_id', $condition);

        return $this;
    }

    public function getVendor()
    {
        return 1;
    }

    public function joinUrlRewrite()
    {
/*         $this->join(
            'url_rewrite',
            'category_id = entity_id',
            ['request_path'],
            sprintf(
                '{{table}}.is_autogenerated = 1 AND {{table}}.store_id = %d AND {{table}}.entity_type = \'%s\'',
                $this->getVendor(),
                'vendor_category'
            ),
            'left'
        );
 */
        return $this;
    }

    /**
     * Add category path filter.
     *
     * @param string $regexp
     *
     * @return $this
     */
    public function addPathFilter($regexp)
    {
        $this->addFieldToFilter('path', ['regexp' => $regexp]);

        return $this;
    }

    /**
     * Add active category filter.
     *
     * @return $this
     */
    public function addIsActiveFilter()
    {
        $this->addFieldToFilter('is_active', 1);

        return $this;
    }

    /**
     * Add url rewrite rules to collection.
     *
     * @return $this
     */
    public function addUrlRewriteToResult()
    {
        $this->joinUrlRewrite();

        return $this;
    }

    /**
     * Add category path filter.
     *
     * @param array|string $paths
     *
     * @return $this
     */
    public function addPathsFilter($paths)
    {
        if (!is_array($paths)) {
            $paths = [$paths];
        }
        $connection = $this->getResource()->getConnection();
        $cond = [];
        foreach ($paths as $path) {
            $cond[] = $connection->quoteInto('e.path LIKE ?', "{$path}%");
        }
        if ($cond) {
            $this->getSelect()->where(implode(' OR ', $cond));
        }

        return $this;
    }

    /**
     * Add category level filter.
     *
     * @param int|string $level
     *
     * @return $this
     */
    public function addLevelFilter($level)
    {
        $this->addFieldToFilter('level', ['lteq' => $level]);

        return $this;
    }

    /**
     * @param \Vnecoms\Vendors\Model\Vendor $vendor
     *
     * @return $this
     */
    public function addVendorFilter($vendor)
    {
        $this->addFieldToFilter('vendor_id', ['eq' => $vendor->getId()]);

        return $this;
    }

    /**
     * Add root category filter.
     *
     * @return $this
     */
    public function addRootLevelFilter()
    {
        $this->addFieldToFilter('path', ['neq' => '1']);
        $this->addLevelFilter(1);

        return $this;
    }

    /**
     * Add order field.
     *
     * @param string $field
     *
     * @return $this
     */
    public function addOrderField($field)
    {
        $this->setOrder($field, self::SORT_ORDER_ASC);

        return $this;
    }

    /**
     * Getter for _productTable.
     *
     * @return string
     */
    public function getProductTable()
    {
        if (empty($this->_productTable)) {
            $this->_productTable = $this->getTable('ves_vendorscategory_category_product');
        }

        return $this->_productTable;
    }

    /**
     * Load product count for specified items.
     *
     * @param array $items
     * @param bool  $countRegular get product count for regular (non-anchor) categories
     * @param bool  $countAnchor  get product count for anchor categories
     *
     * @return $this
     * @SuppressWarnings(PHPMD.CyclomaticComplexity)
     * @SuppressWarnings(PHPMD.UnusedLocalVariable)
     */
    public function loadProductCount($items, $countRegular = true, $countAnchor = true)
    {
        $anchor = [];
        $regular = [];

        foreach ($items as $item) {
            $regular[$item->getId()] = $item;
        }

        if ($countRegular) {
            // Retrieve regular categories product counts
            $regularIds = array_keys($regular);
            if (!empty($regularIds)) {
                $select = $this->_conn->select();
                $select->from(
                    ['main_table' => $this->getProductTable()],
                    ['category_id', new \Zend_Db_Expr('COUNT(main_table.product_id)')]
                )->where(
                    $this->_conn->quoteInto('main_table.category_id IN(?)', $regularIds)
                )->group(
                    'main_table.category_id'
                );

                $counts = $this->_conn->fetchPairs($select);
                foreach ($regular as $item) {
                    if (isset($counts[$item->getId()])) {
                        $item->setProductCount($counts[$item->getId()]);
                    } else {
                        $item->setProductCount(0);
                    }
                }
            }
        }

        return $this;
    }

    /**
     * Load categories product count.
     */
    protected function _loadProductCount()
    {
        $this->loadProductCount($this->_items, true, true);
    }
}
